<?php
require __DIR__.'/bootstrap.php';
if(!$admin){http_response_code(403);exit('Admin access required.');}
if(!crm_queue_ready()){header('Location: update.php');exit;}
$rows=query("SELECT u.name,u.employee_id,u.campaign_access,COALESCE(s.mode,'offline') mode,s.break_reason,s.changed_at,s.active_lead_id,l.hospital_name FROM sales_crm_users u LEFT JOIN sales_crm_agent_state s ON s.employee_id=u.employee_id LEFT JOIN sales_crm_leads l ON l.id=s.active_lead_id WHERE u.role='agent' AND u.active=1 ORDER BY u.name")->get_result();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent availability | Talkvia CRM</title><link rel="stylesheet" href="style.css?v=5"></head><body><header><a href="index.php" class="brand">Talkvia <span>Sales CRM</span></a><nav><a href="reports.php">Calling reports</a><a href="index.php">Back to CRM</a></nav></header><main><section class="panel"><div class="heading"><h1>Agent availability</h1><a href="queue-monitor.php">Refresh</a></div><p>Last recorded CRM availability; this is not a live connection indicator.</p><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Campaign access</th><th>Status</th><th>Since (IST)</th><th>Break reason</th><th>Current hospital</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><small><?=e($r['employee_id'])?></small></td><td><?=e($r['campaign_access'])?></td><td><?=e(ucfirst($r['mode']))?></td><td><?=e(displaytime($r['changed_at'])?:'—')?></td><td><?=e($r['break_reason']?:'—')?></td><td><?=e($r['hospital_name']?:'—')?></td></tr><?php endforeach ?></tbody></table></div></section><section class="panel"><h2>Recent queue activity</h2><?php $events=query('SELECT ev.*,u.name FROM sales_crm_agent_events ev LEFT JOIN sales_crm_users u ON u.employee_id=ev.employee_id ORDER BY ev.id DESC LIMIT 100')->get_result();foreach($events as $ev):?><article class="history"><strong><?=e($ev['name']?:$ev['employee_id'])?></strong> · <?=e(str_replace('_',' ',$ev['event']))?> · <?=e(displaytime($ev['created_at']))?> IST <small><?=e($ev['reason'])?> <?= $ev['lead_id']?' · Hospital #'.e($ev['lead_id']):''?></small></article><?php endforeach ?></section></main></body></html>
